window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1bf9dc32c07dba6e"]={"versions": [{"id": "FIG-1bf9dc32c07dba6e", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Zweck</h4>\n<p class=\"fig-p\">Das Bild ist ein <strong>informelles, grafisches Strukturdiagramm</strong> in AUTOSAR-Notation. Es ist kein UML-Diagramm im strengen Sinn. Es zeigt eine Software-Komponente als Blackbox mit ihren Ports und den Verbindungen nach außen. Es dient als Einführungsbeispiel für die grafische Darstellung von Software-Komponenten im Software Component Template (CP R24-11, Kap. 3.2.1). Die Kernaussage: Eine Komponente kapselt ihre Implementierung und legt nur wohldefinierte Verbindungspunkte, die PortPrototypes, offen.</p>\n<h4 class=\"fig-section-h4\">2. Beteiligte Komponenten &amp; Entitäten</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software-Component:</strong> großes graues Rechteck mit dem Label „AUTOSAR Software-Component\". Es steht für einen SwComponentType, im Textkontext konkret für einen AtomicSwComponentType.</li>\n<li><strong>PortPrototypes am rechten Rand der Komponente</strong> (kleine Quadrate mit Symbol), von oben nach unten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>provided PortPrototype, ClientServerInterface. Das Symbol ist ein Kreis, der Server-Anbieter.</li>\n<li>required PortPrototype, ClientServerInterface. Das Symbol ist ein Halbkreis (Socket).</li>\n<li>provided PortPrototype, SenderReceiverInterface. Das Symbol ist ein nach rechts zeigendes, gefülltes Dreieck.</li>\n<li>required PortPrototype, SenderReceiverInterface. Das Symbol ist ein nach links zeigendes, gefülltes Dreieck.</li>\n<li>Ein Port mit invertiertem Symbol (schwarzes Quadrat, weißes Dreieck nach links). Er ist nicht beschriftet. Daneben steht ein schwarzer Balken, der vermutlich ein geschwärzter bzw. weggelassener Platzhalter für einen Text ist. Die Bedeutung lässt sich dem Bild nicht eindeutig entnehmen.</li>\n<li>provided PortPrototype, SenderReceiverInterface, mit einer Notiz „attributes\".</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Externe Gegenstellen</strong> (Symbole außerhalb der Komponente): ein Kreis-Port (Client-Server) und ein Dreieck-Port (Sender-Receiver). Sie gehören zu anderen, nicht dargestellten Komponenten.</li>\n<li><strong>SwConnector:</strong> zwei beschriftete Linien zwischen den Ports und den externen Gegenstellen.</li>\n<li><strong>Annotationen:</strong> „PortPrototype characterised by Portinterface\" (Pfeil auf den obersten Port) und die Notiz „attributes\" (Dokument-Symbol mit Pfeil auf den untersten Port).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Technische Abläufe &amp; Beziehungen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt keinen zeitlichen Ablauf, keine Aufrufe, Parameter oder Rückgaben. Es zeigt nur statische Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Jeder PortPrototype wird durch ein <strong>PortInterface</strong> charakterisiert. Hier sind das ClientServerInterface (Operationen) und SenderReceiverInterface (Datenelemente).</li>\n<li><strong>Provided</strong> und <strong>required</strong> Ports unterscheiden sich in der Rolle. Provided-Ports bieten etwas an, required-Ports nutzen es. Die Symbole kodieren Interface-Typ und Richtung:</li>\n<li>Kreis und Halbkreis stehen für Client-Server (Server bzw. Client).</li>\n<li>Das Dreieck steht für Sender-Receiver, mit der Spitze in Datenflussrichtung.</li>\n<li>Ein <strong>SwConnector</strong> verbindet einen required-Port der Komponente mit einem kompatiblen provided-Port einer anderen Komponente. In der Abbildung sind zwei solche Verbindungen sichtbar: eine Client-Server- und eine Sender-Receiver-Verbindung.</li>\n<li>Die Ports ohne gezeichnete Linie (Port 1, 3 und 6) sind in diesem Ausschnitt unverbunden.</li>\n<li>Die Notiz „attributes\" deutet an, dass Ports weitere Attribute tragen können, etwa Kommunikations- oder Initialisierungsattribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Besondere technische Details &amp; Normative Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Es gilt das Prinzip der <strong>Kapselung</strong>: Die Außenwirkung einer Komponente besteht ausschließlich aus ihren PortPrototypes.</li>\n<li>Ein SwConnector verbindet nur Ports mit <strong>kompatiblen PortInterfaces</strong>. Dabei gehört auf eine Seite ein provided- und auf die andere ein required-Port.</li>\n<li>Das Diagramm nennt keine Multiplizitäten, Konfigurationsparameter, Fehlerbehandlung oder Abbruchbedingungen.</li>\n<li>Die Abbildung ist laut Titel eine <strong>exemplarische</strong> Darstellung. Sie ist keine vollständige oder normative Notation.</li>\n<li>Die Details der abgeschwärzten Stelle und des Ports 5 sind im Bild nicht erkennbar. Hier sollte nichts hineininterpretiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">5. Zusammenfassung für Entwickler</h4>\n<p class=\"fig-p\">Die Abbildung zeigt, dass eine AUTOSAR-Komponente ausschließlich über provided und required Ports mit Client-Server- oder Sender-Receiver-Interfaces kommuniziert. Diese Ports werden über SwConnectors mit kompatiblen Gegenports verbunden. Für Entwickler und Integratoren heißt das: Ports und Interfaces sind die Schnittstellenverträge, auf deren Basis Komponenten unabhängig vom Steuergerät und von der Implementierung verschaltet werden.</p>"}, {"id": "FIG-1a0e821227f3b891", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Bild ist ein <strong>informelles, grafisches Strukturdiagramm</strong> in AUTOSAR-Notation. Es ist kein UML-Diagramm im strengen Sinn. Es zeigt eine Software-Komponente als Blackbox mit ihren Ports und den Verbindungen nach außen. Es dient als Einführungsbeispiel für die grafische Darstellung von Software-Komponenten im Software Component Template (CP R24-11, Kap. 3.2.1). Die Kernaussage: Eine Komponente kapselt ihre Implementierung und legt nur wohldefinierte Verbindungspunkte, die PortPrototypes, offen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software-Component:</strong> großes weißes Rechteck mit dem Label „AUTOSAR Software-Component\". Es steht für einen SwComponentType, im Textkontext konkret für einen AtomicSwComponentType.</li>\n<li><strong>PortPrototypes am rechten Rand der Komponente</strong> (kleine Quadrate mit Symbol), von oben nach unten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Provided PortPrototype, ClientServerInterface. Das Symbol ist ein Kreis, der Server-Anbieter.</li>\n<li>Required PortPrototype, ClientServerInterface. Das Symbol ist ein Halbkreis (Socket).</li>\n<li>Provided PortPrototype, SenderReceiverInterface. Das Symbol ist ein nach rechts zeigendes, gefülltes Dreieck.</li>\n<li>Required PortPrototype, SenderReceiverInterface. Das Symbol ist ein nach links zeigendes, gefülltes Dreieck.</li>\n<li>Ein Port mit invertiertem Symbol (schwarzes Quadrat, weißes Dreieck nach links). Er ist nicht beschriftet. Daneben steht ein schwarzer Balken, der vermutlich ein geschwärzter bzw. weggelassener Platzhalter für einen Text ist. Die Bedeutung lässt sich dem Bild nicht eindeutig entnehmen.</li>\n<li>Provided PortPrototype, SenderReceiverInterface, mit einer Notiz „attributes\".</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Externe Gegenstellen</strong> (Symbole außerhalb der Komponente): ein Kreis-Port (Client-Server) und ein Dreieck-Port (Sender-Receiver). Sie gehören zu anderen, nicht dargestellten Komponenten.</li>\n<li><strong>SwConnector:</strong> zwei beschriftete Linien zwischen den Ports und den externen Gegenstellen.</li>\n<li><strong>Annotationen:</strong> „PortPrototype characterized by PortInterface\" (Pfeil auf den obersten Port) und die Notiz „attributes\" (Dokument-Symbol mit Pfeil auf den untersten Port).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt keinen zeitlichen Ablauf, keine Aufrufe, Parameter oder Rückgaben. Es zeigt nur statische Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Jeder PortPrototype wird durch ein <strong>PortInterface</strong> charakterisiert. Hier sind das ClientServerInterface (Operationen) und SenderReceiverInterface (Datenelemente).</li>\n<li><strong>Provided</strong> und <strong>required</strong> Ports unterscheiden sich in der Rolle. Provided-Ports bieten etwas an, required-Ports nutzen es. Die Symbole kodieren Interface-Typ und Richtung:</li>\n<li>Kreis und Halbkreis stehen für Client-Server (Server bzw. Client).</li>\n<li>Das Dreieck steht für Sender-Receiver, mit der Spitze in Datenflussrichtung.</li>\n<li>Ein <strong>SwConnector</strong> verbindet einen required-Port der Komponente mit einem kompatiblen provided-Port einer anderen Komponente. In der Abbildung sind zwei solche Verbindungen sichtbar: eine Client-Server- und eine Sender-Receiver-Verbindung.</li>\n<li>Die Ports ohne gezeichnete Linie (Port 1, 3 und 6) sind in diesem Ausschnitt unverbunden.</li>\n<li>Die Notiz „attributes\" deutet an, dass Ports weitere Attribute tragen können, etwa Kommunikations- oder Initialisierungsattribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Es gilt das Prinzip der <strong>Kapselung</strong>: Die Außenwirkung einer Komponente besteht ausschließlich aus ihren PortPrototypes.</li>\n<li>Ein SwConnector verbindet nur Ports mit <strong>kompatiblen PortInterfaces</strong>. Dabei gehört auf eine Seite ein provided- und auf die andere ein required-Port.</li>\n<li>Das Diagramm nennt keine Multiplizitäten, Konfigurationsparameter, Fehlerbehandlung oder Abbruchbedingungen.</li>\n<li>Die Abbildung ist laut Titel eine <strong>exemplarische</strong> Darstellung. Sie ist keine vollständige oder normative Notation.</li>\n<li>Die Details der abgeschwärzten Stelle und des Ports 5 sind im Bild nicht erkennbar. Hier sollte nichts hineininterpretiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">5. Zusammenfassung für Entwickler</h4>\n<p class=\"fig-p\">Die Abbildung zeigt, dass eine AUTOSAR-Komponente ausschließlich über provided und required Ports mit Client-Server- oder Sender-Receiver-Interfaces kommuniziert. Diese Ports werden über SwConnectors mit kompatiblen Gegenports verbunden. Für Entwickler und Integratoren heißt das: Ports und Interfaces sind die Schnittstellenverträge, auf deren Basis Komponenten unabhängig vom Steuergerät und von der Implementierung verschaltet werden.</p>"}], "trans": [{"from": "FIG-1bf9dc32c07dba6e", "to": "FIG-1a0e821227f3b891", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software-Component</strong>: Hintergrundfüllung des Hauptrechtecks von Hellgrau zu Weiß (transparent) geändert.</li>\n<li><strong>PortPrototype-Beschriftungen</strong>: Schreibweise von „provided“ und „required“ zu Großschreibung („Provided“, „Required“) vereinheitlicht; nachgestellte Satzzeichen entfernt.</li>\n<li><strong>Annotation</strong>: Beschriftung von britischer Schreibweise „PortPrototype characterised by Portinterface“ auf amerikanische Schreibweise und Binnenmajuskel „PortPrototype characterized by PortInterface“ geändert.</li>\n<li><strong>Layout & Typografie</strong>: Grafik mit überarbeiteter Schriftart und angepasstem Spacing neu gesetzt.</li>\n</ul>"}]};
